    ok: false,
    status: "unreachable",
    httpStatus: lastStatus,
    message: lastError
      ? `Could not reach Duel API at ${base}: ${lastError}`
      : `Could not reach Duel API at ${base}. Check your network or try again later.`,
  };
}
