    assert.equal(validateApiKey(KEY2), true);
  });

  it("trims surrounding whitespace", () => {
    assert.equal(validateApiKey("  " + KEY + "\n"), true);
  });

  it("rejects empty, null and undefined", () => {
    assert.equal(validateApiKey(""), false);
    assert.equal(validateApiKey(null), false);
    assert.equal(validateApiKey(undefined), false);
    assert.equal(validateApiKey("   "), false);
  });

  it("rejects foreign provider keys", () => {
    assert.equal(validateApiKey("[REDACTED_API_KEY]"), false);
    assert.equal(validateApiKey("sk-proj-abcdef"), false);
  });

  it("rejects wrong segment lengths", () => {
    assert.equal(validateApiKey("duel_a1b2c3d_" + "a".repeat(32)), false);
    assert.equal(validateApiKey("duel_a1b2c3d4e_" + "a".repeat(32)), false);
    assert.equal(validateApiKey("duel_a1b2c3d4_" + "a".repeat(31)), false);
    assert.equal(validateApiKey("duel_a1b2c3d4_" + "a".repeat(33)), false);
  });

  it("rejects non base62 characters and missing prefix", () => {
    assert.equal(validateApiKey("duel_a1b2c3d-_" + "a".repeat(32)), false);
    assert.equal(validateApiKey("duel_a1b2c3d4_" + "a".repeat(31) + "-"), false);
    assert.equal(validateApiKey("DUEL_a1b2c3d4_" + "a".repeat(32)), false);
    assert.equal(validateApiKey("a1b2c3d4_" + "a".repeat(32)), false);
  });

  it("rejects trailing junk after the secret", () => {
    assert.equal(validateApiKey(KEY + "_extra"), false);
  });

  it("rejects non string input", () => {
    assert.equal(validateApiKey(123 as unknown as string), false);
    assert.equal(validateApiKey({} as unknown as string), false);
  });
