    const urls: string[] = [];
    const methods: string[] = [];
    globalThis.fetch = (async (url: string, init: RequestInit) => {
      urls.push(String(url));
      methods.push(String(init.method));
      return new Response("", { status: 500 });
    }) as unknown as typeof fetch;

    const res = await checkConnectivity(KEY, "https://p.example/v1");
    assert.deepEqual(urls, [
      "https://p.example/v1/models",
      "https://p.example/v1/health",
      "https://p.example/v1",
    ]);
    assert.deepEqual(methods, ["GET", "GET", "HEAD"]);
    assert.equal(res.ok, false);
    assert.equal(res.status, "unreachable");
    assert.equal(res.httpStatus, 500);
    assert.match(res.message, /HTTP 500/);
  });

  it("never throws when fetch rejects", async () => {
    globalThis.fetch = (async () => {
      throw new Error("ECONNREFUSED boom");
    }) as typeof fetch;
    const res = await checkConnectivity(KEY, "https://p.example/v1");
    assert.equal(res.ok, false);
    assert.equal(res.status, "unreachable");
    assert.equal(res.httpStatus, undefined);
    assert.ok(
      res.message.includes(
        "Could not reach Duel API at https://p.example/v1: ECONNREFUSED boom",
      ),
    );
  });

  it("succeeds on a later probe", async () => {
    let n = 0;
    globalThis.fetch = (async () => {
      n += 1;
      if (n < 3) throw new Error("nope");
      return new Response("", { status: 204 });
    }) as typeof fetch;
    const res = await checkConnectivity(KEY, "https://p.example/v1");
    assert.equal(n, 3);
    assert.equal(res.ok, true);
    assert.equal(res.status, "ok");
    assert.equal(res.httpStatus, 204);
  });
});
